#include <stdio.h>
#include <stdlib.h>
typedef int element;
typedef struct StackNode {
    element item;
    struct StackNode *link;
} StackNode;
typedef struct {
    StackNode *top;
} LinkedStackType;
// 삽입 함수
void push(LinkedStackType *s, element item)
{
    StackNode *temp=(StackNode *)malloc(sizeof(StackNode));
    if( temp == NULL ){
        fprintf(stderr, "메모리 할당에러\n");
        return;
    }
    else{
        temp->item = item;
        temp->link = s->top;
        s->top = temp;
    }
}
int main(void)
{
    LinkedStackType s = { NULL };
    /* 앞선 push로 노드 3개가 쌓여 있다고 가정 */
    push(&s, 40);
    return 0;
}

